select pa.id, pa.code, pad.is_urgent as isUrgent, pa.approve_status as approveStatus, pa.is_first_mass_product as isFirstMassProduct, pad.create_po_type as createPoType, pad.sku_no as skuNo, pad.product_name as productName, pad.variant_property as variantProperty, pad.plan_delivery_date as planDeliveryDate, pad.apply_qty as applyQty, parp.realPurchaseQty, pad.receive_qty as receiveQty, pad.stock_in_qty as stockInQty, pad.dest_warehouse_name as destWarehouseName, pad.remark, pa.approve_user_name as approveUserName, pa.create_user_name as createUserName, pa.create_time as createTime from purchase_application pa inner join purchase_application_detail pad on pa.id = pad.purchase_application_id and pad.is_deleted = false left join ( select parp.purchase_application_detail_id,sum(pod.purchase_qty) as realPurchaseQty from purchase_application_ref_po parp left join purchase_order_detail pod on parp.purchase_order_detail_id = pod.id and pod.is_deleted = false where parp.is_deleted = false group by parp.purchase_application_detail_id ) parp on pad.id = parp.purchase_application_detail_id
pa.is_deleted = false
and pa.code like concat('%',#{params.code},'%')
and pad.product_name like concat('%',#{params.productName},'%')
and pad.is_urgent = #{params.isUrgent}
and pa.is_first_mass_product = #{params.isFirstMassProduct}
and pa.approve_status in
#{item}
and pad.create_po_type in
#{item}
