#{item}
and pa.create_user_id in
#{item}
and pad.plan_delivery_date >= #{params.planDeliveryDateList[0]} and (#{params.planDeliveryDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pad.plan_delivery_date
and pa.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pa.create_time
and pa.approve_time >= #{params.approveTimeList[0]} and (#{params.approveTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pa.approve_time
ORDER BY
${item.field} ${item.sort}
