select pa.id, pa.code, pa.approve_status as approveStatus, case pa.approve_status when 'waitSubmit' then '待提交' when 'approveIng' then '审核中' when 'reject' then '审核不通过' when 'approve' then '已审核' end as approveStatusName, case pa.is_first_mass_product when true then '是' when false then '否' end as isFirstMassProduct, case pad.create_po_type when '0' then '未生成' when '1' then '部分生成' when '2' then '已生成' end as createPoTypeName, pad.sku_no as skuNo, pad.product_name as productName, pad.plan_delivery_date as planDeliveryDate, pad.apply_qty as applyQty, parp.realPurchaseQty, pad.receive_qty as receiveQty, pad.stock_in_qty as stockInQty, pad.dest_warehouse_name as destWarehouseName, pad.remark, pa.approve_user_name as approveUserName, pa.create_user_name as createUserName, pa.create_time as createTime from purchase_application pa left join purchase_application_detail pad on pa.id = pad.purchase_application_id and pad.is_deleted = false left join ( select parp.purchase_application_detail_id,sum(pod.purchase_qty) as realPurchaseQty from purchase_application_ref_po parp left join purchase_order_detail pod on parp.purchase_order_detail_id = pod.id and pod.is_deleted = false where parp.is_deleted = false group by parp.purchase_application_detail_id ) parp on pad.id = parp.purchase_application_detail_id
